-- Plan « Endurance aéro : tenir la TT » (4 semaines) : 14 séances,
-- objectif aéro et indicateur de réussite (passages en TT validés) par séance.
-- Textes en 9 langues assemblés depuis des gabarits par type. Rejouable.

WITH tpl(typ, lang, name, obj, info) AS (VALUES

('e_cont', 'fr', 'Endurance TT {n}×{d}', 'Tenir la position TT en endurance (65-72 % FTP), sans se relever pendant les blocs. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Endurance fondamentale en position TT : intensité facile pour que toute l''attention aille à la tenue (tête basse, épaules relâchées, appui stable). Les blocs s''allongent d''une semaine à l''autre.'),
('e_cont', 'en', 'TT endurance {n}×{d}', 'Hold the TT position at endurance pace (65-72% FTP) without sitting up during the blocks. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Base endurance in the TT position: easy intensity so all your attention goes to holding it (head low, shoulders relaxed, stable support). The blocks get longer every week.'),
('e_cont', 'es', 'Resistencia TT {n}×{d}', 'Mantener la posición TT a ritmo de resistencia (65-72 % FTP) sin incorporarte en los bloques. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Resistencia básica en posición TT: intensidad suave para que toda la atención vaya a mantenerla (cabeza baja, hombros relajados, apoyo estable). Los bloques se alargan cada semana.'),
('e_cont', 'it', 'Resistenza TT {n}×{d}', 'Tenere la posizione TT a ritmo di resistenza (65-72 % FTP) senza rialzarti nei blocchi. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Resistenza di base in posizione TT: intensità facile perché l''attenzione vada tutta alla tenuta (testa bassa, spalle rilassate, appoggio stabile). I blocchi si allungano ogni settimana.'),
('e_cont', 'de', 'TT-Ausdauer {n}×{d}', 'Die TT-Position im Grundlagentempo (65-72 % FTP) halten, ohne dich in den Blöcken aufzurichten. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Grundlagenausdauer in TT-Position: leichte Intensität, damit die ganze Aufmerksamkeit dem Halten gilt (Kopf tief, Schultern locker, stabile Auflage). Die Blöcke werden jede Woche länger.'),
('e_cont', 'nl', 'TT-duur {n}×{d}', 'De TT-houding vasthouden op duurtempo (65-72 % FTP) zonder overeind te komen tijdens de blokken. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Basisduur in TT-houding: lichte intensiteit zodat al je aandacht naar het vasthouden gaat (hoofd laag, schouders ontspannen, stabiele steun). De blokken worden elke week langer.'),
('e_cont', 'pt', 'Resistência TT {n}×{d}', 'Manter a posição TT em ritmo de resistência (65-72 % FTP) sem levantar o tronco nos blocos. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Resistência de base na posição TT: intensidade leve para que toda a atenção vá para mantê-la (cabeça baixa, ombros relaxados, apoio estável). Os blocos ficam mais longos a cada semana.'),
('e_cont', 'ja', 'TT持久 {n}×{d}', '持久ペース（65〜72 % FTP）でTTポジションを保ち、ブロック中は起き上がらない。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', 'TTポジションでの基礎持久力：強度は楽にして保つことに集中（頭を低く、肩の力を抜き、安定した支え）。ブロックは週ごとに長くなります。'),
('e_cont', 'tr', 'TT dayanıklılık {n}×{d}', 'Dayanıklılık temposunda (%65-72 FTP) TT pozisyonunu koru, bloklarda doğrulma. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'TT pozisyonunda temel dayanıklılık: tüm dikkatin pozisyonu korumakta olsun diye kolay yoğunluk (baş aşağıda, omuzlar gevşek, sabit destek). Bloklar her hafta uzar.'),
('e_long', 'fr', 'Fond TT {m}''', 'Accumuler le plus long temps en TT de la semaine à 70-72 % FTP. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Sortie longue : de longs blocs en TT entrecoupés de courtes pauses redressées. Cherche une position que tu peux tenir, pas la plus basse.'),
('e_long', 'en', 'Long TT ride {m}''', 'Build up the longest TT time of the week at 70-72% FTP. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Long ride: long TT blocks broken up by short upright breaks. Find a position you can hold, not the lowest one.'),
('e_long', 'es', 'Fondo TT {m}''', 'Acumular el mayor tiempo en TT de la semana al 70-72 % FTP. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Salida larga: bloques largos en TT con pausas cortas erguido. Busca una posición que puedas mantener, no la más baja.'),
('e_long', 'it', 'Fondo TT {m}''', 'Accumulare il tempo in TT più lungo della settimana al 70-72 % FTP. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Uscita lunga: lunghi blocchi in TT con brevi pause eretto. Cerca una posizione che puoi tenere, non la più bassa.'),
('e_long', 'de', 'Lange TT-Fahrt {m}''', 'Die längste TT-Zeit der Woche bei 70-72 % FTP sammeln. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Lange Fahrt: lange TT-Blöcke mit kurzen aufrechten Pausen. Such eine Position, die du halten kannst, nicht die tiefste.'),
('e_long', 'nl', 'Lange TT-rit {m}''', 'De langste TT-tijd van de week opbouwen op 70-72 % FTP. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Lange rit: lange TT-blokken met korte pauzes rechtop. Zoek een houding die je kunt volhouden, niet de laagste.'),
('e_long', 'pt', 'Fundo TT {m}''', 'Acumular o maior tempo em TT da semana a 70-72 % FTP. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Treino longo: blocos longos em TT com pausas curtas ereto. Procure uma posição que consiga manter, não a mais baixa.'),
('e_long', 'ja', 'ロングTT {m}''', '70〜72 % FTPで週で最も長いTT時間を積み上げる。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', 'ロングライド：短いアップライト休憩を挟んだ長いTTブロック。一番低い姿勢ではなく、維持できる姿勢を探して。'),
('e_long', 'tr', 'Uzun TT sürüş {m}''', '%70-72 FTP''de haftanın en uzun TT süresini biriktir. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Uzun sürüş: kısa dik molalarla bölünmüş uzun TT blokları. En alçak değil, koruyabileceğin bir pozisyon bul.'),
('e_tempo', 'fr', 'Tempo TT {n}×{d}', 'Tenir la position TT au tempo (80-85 % FTP), quand la respiration s''accélère. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Le tempo est l''allure d''un CLM long ou d''un triathlon longue distance : assez dur pour que le haut du corps veuille se relever. Récupère redressé entre les blocs.'),
('e_tempo', 'en', 'TT tempo {n}×{d}', 'Hold the TT position at tempo (80-85% FTP), when breathing gets faster. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Tempo is the pace of a long TT or a long-distance triathlon: hard enough that your upper body wants to sit up. Recover upright between blocks.'),
('e_tempo', 'es', 'Tempo TT {n}×{d}', 'Mantener la posición TT a tempo (80-85 % FTP), cuando la respiración se acelera. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'El tempo es el ritmo de una CRI larga o de un triatlón de larga distancia: lo bastante duro para que el tronco quiera incorporarse. Recupera erguido entre bloques.'),
('e_tempo', 'it', 'Tempo TT {n}×{d}', 'Tenere la posizione TT a ritmo tempo (80-85 % FTP), quando il respiro accelera. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Il tempo è il ritmo di una crono lunga o di un triathlon lungo: abbastanza duro da voler rialzare il busto. Recupera eretto tra i blocchi.'),
('e_tempo', 'de', 'TT-Tempo {n}×{d}', 'Die TT-Position im Tempobereich (80-85 % FTP) halten, wenn die Atmung schneller wird. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Tempo ist das Tempo eines langen Zeitfahrens oder einer Langdistanz: hart genug, dass sich der Oberkörper aufrichten will. Zwischen den Blöcken aufrecht erholen.'),
('e_tempo', 'nl', 'TT-tempo {n}×{d}', 'De TT-houding vasthouden op tempo (80-85 % FTP), als de ademhaling versnelt. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Tempo is het tempo van een lange tijdrit of lange-afstandstriatlon: zwaar genoeg dat je bovenlijf overeind wil. Herstel rechtop tussen de blokken.'),
('e_tempo', 'pt', 'Tempo TT {n}×{d}', 'Manter a posição TT em ritmo tempo (80-85 % FTP), quando a respiração acelera. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'O tempo é o ritmo de um contrarrelógio longo ou de um triatlo de longa distância: duro o bastante para o tronco querer levantar. Recupere ereto entre os blocos.'),
('e_tempo', 'ja', 'TTテンポ {n}×{d}', '呼吸が速くなるテンポ（80〜85 % FTP）でTTポジションを保つ。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', 'テンポはロングTTやロングディスタンス・トライアスロンのペース。上体を起こしたくなる強さです。ブロックの間は起き上がって回復。'),
('e_tempo', 'tr', 'TT tempo {n}×{d}', 'Nefes hızlandığında tempoda (%80-85 FTP) TT pozisyonunu koru. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Tempo, uzun bir zamana karşı yarışın ya da uzun mesafe triatlonun temposudur: üst gövdenin doğrulmak isteyeceği kadar zor. Bloklar arasında dik toparlan.')
), wk(lang, p) AS (VALUES ('fr', 'S'), ('en', 'W'), ('es', 'S'), ('it', 'S'), ('de', 'W'), ('nl', 'W'), ('pt', 'S'), ('ja', 'W'), ('tr', 'H')
