('endurance_tt_4w_w4s1', 'e_tempo', 4, '2', '10''', 45, 2, 1200, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 80.0, "power_end": 60.0, "duration_work": 600, "duration_recup": 300, "repetitions": 2, "position": "prolongateurs", "position_recup": "cocottes"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "endurance_tt_4w_lc_start", "duration": 12}, {"at": 1200, "key": "endurance_tt_4w_lc_up", "duration": 10}, {"at": 1490, "key": "endurance_tt_4w_lc_start", "duration": 12}, {"at": 2100, "key": "endurance_tt_4w_lc_up", "duration": 10}]'::jsonb),
('endurance_tt_4w_w4s2', 'e_cont', 4, '1', '50''', 65, 1, 3000, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 3000, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "endurance_tt_4w_lc_start", "duration": 12}, {"at": 2100, "key": "endurance_tt_4w_lc_mid", "duration": 12}]'::jsonb),
('endurance_tt_4w_w4s3', 'e_cont', 4, '2', '15''', 51, 2, 1800, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 68.0, "power_end": 68.0, "duration_work": 900, "duration_recup": 180, "repetitions": 2, "position": "prolongateurs", "position_recup": "cocottes"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "endurance_tt_4w_lc_start", "duration": 12}, {"at": 1500, "key": "endurance_tt_4w_lc_up", "duration": 10}, {"at": 1670, "key": "endurance_tt_4w_lc_start", "duration": 12}, {"at": 2580, "key": "endurance_tt_4w_lc_up", "duration": 10}]'::jsonb)
), built AS (
  SELECT s.*,
    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, replace(t.obj, '{k}', s.k::text)) FROM tpl t WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
INSERT INTO public.training_sessions (name, info, objectif, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT b.skey || '_name', b.skey || '_info', b.skey || '_objectif',
  jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  b.minutes, false, b.lc,
  jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"endurance_tt_4w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "endurance_tt_4w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "endurance_tt_4w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "endurance_tt_4w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  b.aero
FROM built b
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions ts WHERE ts.name = b.skey || '_name');

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'endurance_tt_4w_name', 'endurance_tt_4w_description', 'endurance_tt_4w_objective', 4, 'intermediate', 'training', 4, true, '{"name": {"fr": "Endurance aéro : tenir la TT", "en": "Aero endurance: hold the TT", "es": "Resistencia aero: mantener el TT", "it": "Resistenza aero: tenere la TT", "de": "Aero-Ausdauer: TT halten", "nl": "Aero-duur: de TT vasthouden", "pt": "Resistência aero: manter o TT", "ja": "エアロ持久：TTを保つ", "tr": "Aero dayanıklılık: TT''yi koru"}, "objective": {"fr": "Tenir la position TT 50 minutes d''affilée en endurance et 3×12'' au tempo.", "en": "Hold the TT position for 50 minutes in a row at endurance pace and 3×12'' at tempo.", "es": "Mantener la posición TT 50 minutos seguidos en resistencia y 3×12'' a tempo.", "it": "Tenere la posizione TT 50 minuti di fila in resistenza e 3×12'' a ritmo tempo.", "de": "Die TT-Position 50 Minuten am Stück im Grundlagentempo und 3×12'' im Tempobereich halten.", "nl": "De TT-houding 50 minuten aan één stuk op duurtempo en 3×12'' op tempo vasthouden.", "pt": "Manter a posição TT 50 minutos seguidos em resistência e 3×12'' em ritmo tempo.", "ja": "持久ペースで50分連続、テンポで3×12''のTTポジションを保つ。", "tr": "TT pozisyonunu dayanıklılık temposunda aralıksız 50 dakika ve tempoda 3×12'' koru."}, "description": {"fr": "4 semaines, 3 à 4 séances de 45 à 80 minutes, pour allonger le temps passé en position TT. Endurance (65-72 % FTP) en blocs de 15 à 50 minutes, tempo (80-85 % FTP) en blocs de 8 à 12 minutes et une sortie longue par semaine. Chaque séance fixe un nombre de passages en TT à valider.", "en": "4 weeks, 3 to 4 sessions of 45 to 80 minutes, to extend your time in the TT position. Endurance (65-72% FTP) in 15 to 50 minute blocks, tempo (80-85% FTP) in 8 to 12 minute blocks and one long ride a week. Each session sets a number of TT blocks to validate.", "es": "4 semanas, 3 a 4 sesiones de 45 a 80 minutos, para alargar el tiempo en posición TT. Resistencia (65-72 % FTP) en bloques de 15 a 50 minutos, tempo (80-85 % FTP) en bloques de 8 a 12 minutos y una salida larga por semana. Cada sesión fija un número de tramos en TT a validar.", "it": "4 settimane, da 3 a 4 sessioni da 45 a 80 minuti, per allungare il tempo in posizione TT. Resistenza (65-72 % FTP) in blocchi da 15 a 50 minuti, tempo (80-85 % FTP) in blocchi da 8 a 12 minuti e un''uscita lunga a settimana. Ogni sessione fissa un numero di tratti in TT da validare.", "de": "4 Wochen, 3 bis 4 Einheiten von 45 bis 80 Minuten, um die Zeit in TT-Position zu verlängern. Grundlage (65-72 % FTP) in Blöcken von 15 bis 50 Minuten, Tempo (80-85 % FTP) in Blöcken von 8 bis 12 Minuten und eine lange Fahrt pro Woche. Jede Einheit legt eine Anzahl zu bestehender TT-Abschnitte fest.", "nl": "4 weken, 3 tot 4 sessies van 45 tot 80 minuten, om de tijd in TT-houding te verlengen. Duur (65-72 % FTP) in blokken van 15 tot 50 minuten, tempo (80-85 % FTP) in blokken van 8 tot 12 minuten en één lange rit per week. Elke sessie legt een aantal te halen TT-stukken vast.", "pt": "4 semanas, 3 a 4 sessões de 45 a 80 minutos, para alongar o tempo na posição TT. Resistência (65-72 % FTP) em blocos de 15 a 50 minutos, tempo (80-85 % FTP) em blocos de 8 a 12 minutos e um treino longo por semana. Cada sessão fixa um número de trechos em TT a validar.", "ja": "4週間、45〜80分のセッションを週3〜4回。TTポジションの時間を伸ばします。持久（65〜72 % FTP）は15〜50分のブロック、テンポ（80〜85 % FTP）は8〜12分のブロック、週1回のロングライド。各セッションで達成すべきTTブロック数を設定。", "tr": "4 hafta, TT pozisyonundaki süreyi uzatmak için haftada 45-80 dakikalık 3-4 seans. 15-50 dakikalık bloklarda dayanıklılık (%65-72 FTP), 8-12 dakikalık bloklarda tempo (%80-85 FTP) ve haftada bir uzun sürüş. Her seans onaylanacak TT bölümü sayısını belirler."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'endurance_tt_4w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'endurance_tt_4w_w1s1_name'), (1, 2, 'endurance_tt_4w_w1s2_name'), (1, 3, 'endurance_tt_4w_w1s3_name'), (2, 1, 'endurance_tt_4w_w2s1_name'), (2, 2, 'endurance_tt_4w_w2s2_name'), (2, 3, 'endurance_tt_4w_w2s3_name'), (2, 4, 'endurance_tt_4w_w2s4_name'), (3, 1, 'endurance_tt_4w_w3s1_name'), (3, 2, 'endurance_tt_4w_w3s2_name'), (3, 3, 'endurance_tt_4w_w3s3_name'), (3, 4, 'endurance_tt_4w_w3s4_name'), (4, 1, 'endurance_tt_4w_w4s1_name'), (4, 2, 'endurance_tt_4w_w4s2_name'), (4, 3, 'endurance_tt_4w_w4s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'endurance_tt_4w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);
